const displayNameFor=value=>{const candidate=String(value?.displayName||value?.name||value?.fullName||'').trim();if(candidate&&!/@|\d{6,}|_\d{6,}$/.test(candidate))return candidate;const currentRole=String(value?.role||'').toUpperCase();return currentRole==='OWNER'?'Owner':currentRole==='TRAINER'?'Trainer':currentRole==='MEMBER'?'Member':'User'}; const money=n=>`INR ${Number(n||0).toLocaleString('en-IN')}`; const membershipPrices=Object.fromEntries(fallbackMembershipPlans.map(plan=>[plan.name,plan.price])); const membershipPlanCatalog=fallbackMembershipPlans; const role=s=>String(s||'').toUpperCase();

