const ToastContext=createContext(null);
const toastKind=message=>{const value=String(message||'').toLowerCase();if(/success|added|updated|deleted|created|saved|paid|refreshed|completed/.test(value))return 'success';if(/error|failed|unable|invalid|denied|not found|could not|cannot|must|server|expired|please/.test(value))return 'error';return 'info'};
function Toast({toast,onClose}){const Icon=toast.type==='success'?CheckCircle2:toast.type==='error'?AlertTriangle:Info;return <div className={'toast toast-'+toast.type} role="status"><span className="toast-icon"><Icon size={17}/></span><span className="toast-message">{toast.message}</span><button className="toast-close" aria-label="Dismiss notification" onClick={onClose}><X size={15}/></button></div>}
function ToastProvider({children}){const [toasts,setToasts]=useState([]);const dismiss=useCallback(id=>setToasts(current=>current.filter(toast=>toast.id!==id)),[]);const pushToast=useCallback((message,type)=>{const text=String(message||'').trim();if(!text)return;const id=Date.now()+Math.random();const next={id,message:text,type:type||toastKind(text)};setToasts(current=>[...current.slice(-3),next]);window.setTimeout(()=>dismiss(id),3600)},[dismiss]);useEffect(()=>{const onExpired=()=>pushToast('Your 12-hour session has expired. Please log in again.','error');window.addEventListener('fitlife:session-expired',onExpired);return()=>window.removeEventListener('fitlife:session-expired',onExpired)},[pushToast]);return <ToastContext.Provider value={{pushToast,dismiss}}>{children}<div className="toast-viewport" aria-live="polite" aria-atomic="true">{toasts.map(toast=><Toast key={toast.id} toast={toast} onClose={()=>dismiss(toast.id)}/>)}</div></ToastContext.Provider>}
const useToast=()=>useContext(ToastContext);
