function Landing(){const [login,setLogin]=useState(false);return <>{!login?<div className="landing-shell"><nav className="landing-nav landing-nav--dark"><Brand light/><div className="nav-links"><a href="#about">Experience</a><a href="#features">Method</a><a href="#plans">Membership</a><a href="#contact">Contact</a></div><button className="outline-btn nav-login" onClick={()=>setLogin(true)}><LogIn size={16}/> Owner login</button></nav><main className="landing"><section className="hero hero-editorial"><div className="hero-grid-lines"/><div className="hero-copy"><span className="pill"><span className="pulse"/> TRAIN SMARTER <b>·</b> LIVE BETTER</span><h1>Strength is<br/><em>a practice.</em></h1><p>FitLife is a sharper way to train, track progress and build a body you can rely on.</p><div className="hero-actions"><button className="primary-btn" onClick={()=>setLogin(true)}>Owner login <ArrowUpRight size={16}/></button><a className="ghost-link" href="#plans">View membership <ArrowDown size={15}/></a></div><div className="hero-note"><span className="note-line"/><span>DESIGNED FOR<br/><b>PEOPLE IN MOTION</b></span></div></div><div className="hero-art hero-art--editorial"><div className="hero-orbit orbit-a"/><div className="hero-orbit orbit-b"/><div className="hero-mark">F<span>/</span>L</div><div className="hero-figure"><Dumbbell size={38}/><span>MOVE<br/><em>WITH INTENT</em></span></div><div className="hero-coordinate">12° 58' 04" N<br/><span>FITLIFE / 2026</span></div><div className="hero-vertical">EST. 2021</div></div><div className="hero-scroll">SCROLL TO EXPLORE <ArrowDown size={14}/></div></section><Reveal><section id="about" className="stats-strip"><div className="stats-intro"><span className="eyebrow">THE NUMBERS</span><b>Consistency<br/>compounds.</b></div><AnimatedStat value={500} suffix="+" label="Members"/><AnimatedStat value={12} suffix="" label="Expert trainers"/><AnimatedStat value={18400} suffix="+" label="Workouts logged"/><AnimatedStat value={320} suffix="k" label="Hours trained"/></section></Reveal><Reveal><section id="features" className="experience-section"><div className="experience-heading"><span className="eyebrow">THE FITLIFE METHOD</span><h2>Training with<br/><em>more intention.</em></h2><p>Every detail is built to keep you moving forward—from the first warm-up to the moment progress becomes a habit.</p></div><ExperienceSwitcher/></section></Reveal><Reveal><section className="journey-section"><div className="journey-heading"><span className="eyebrow">YOUR FITNESS JOURNEY</span><h2>One rep at<br/><em>a time.</em></h2></div><div className="journey-track"><div className="journey-line"/><JourneyStep index="01" title="JOIN" detail="Choose a plan that meets you where you are."/><JourneyStep index="02" title="TRAIN" detail="Build a routine that earns your attention."/><JourneyStep index="03" title="TRACK" detail="Make progress visible and momentum real."/><JourneyStep index="04" title="TRANSFORM" detail="Become the person who keeps showing up."/></div></section></Reveal><MembershipPlans onChoose={()=>setLogin(true)}/><Reveal><section className="proof-section"><div className="proof-heading"><div><span className="eyebrow">REAL PEOPLE. REAL PROGRESS.</span><h2>Proof looks<br/><em>good on you.</em></h2></div><p>Small changes become visible when you have the right room, the right people and a reason to keep showing up.</p></div><div className="proof-trust"><span><b>★ 4.9/5</b> member satisfaction</span><span className="trust-rule"/><span>500+ people in motion</span></div><div className="testimonial-rail"><article className="testimonial"><div className="testimonial-top"><span className="member-avatar">RM</span><span className="testimonial-meta"><b>Riya Menon</b><small>QUARTERLY · 8 months</small></span><span className="rating">★★★★★</span></div><p>“I stopped guessing and started seeing the work pay off. The structure keeps me consistent.”</p><span className="quote-mark">“</span></article><article className="testimonial testimonial-featured"><div className="testimonial-top"><span className="member-avatar member-avatar--lime">AK</span><span className="testimonial-meta"><b>Arjun Kapoor</b><small>YEARLY · 14 months</small></span><span className="rating">★★★★★</span></div><p>“FitLife feels focused. The coaches know when to push and when to refine the plan.”</p><span className="quote-mark">“</span><span className="featured-label">MEMBER SPOTLIGHT</span></article><article className="testimonial"><div className="testimonial-top"><span className="member-avatar">NS</span><span className="testimonial-meta"><b>Neha Shah</b><small>MONTHLY · 5 months</small></span><span className="rating">★★★★★</span></div><p>“The best part is the momentum. You can feel the room moving with you.”</p><span className="quote-mark">“</span></article></div></section></Reveal><Reveal><section id="contact" className="final-cta"><div><span className="eyebrow">READY WHEN YOU ARE</span><h2>Your next rep<br/><em>starts here.</em></h2></div><div className="cta-side"><p>Bring the goal. We'll help you build the practice.</p><button className="primary-btn cta-button" onClick={()=>setLogin(true)}>Owner login <ArrowUpRight size={17}/></button><span>OWNER? <button onClick={()=>setLogin(true)}>SIGN IN <ArrowUpRight size={12}/></button></span></div></section></Reveal></main><footer className="landing-footer"><Brand/><span>(c) 2026 FitLife Gym. Built for stronger lives.</span><div><a href="#about">Experience</a><a href="#plans">Plans</a><a href="#contact">Contact</a></div></footer></div>:<Login onBack={()=>setLogin(false)}/>}</>}
function AnimatedStat({value,suffix,label}){const [count,setCount]=useState(0);const ref=useRef(null);useEffect(()=>{const node=ref.current;if(!node)return;let frame;let started=false;const observer=new IntersectionObserver(([entry])=>{if(!entry.isIntersecting||started)return;started=true;const start=performance.now();const tick=now=>{const progress=Math.min((now-start)/1300,1);setCount(Math.floor((1-Math.pow(1-progress,3))*value));if(progress<1)frame=requestAnimationFrame(tick)};frame=requestAnimationFrame(tick)},{threshold:.35});observer.observe(node);return()=>{observer.disconnect();if(frame)cancelAnimationFrame(frame)}},[value]);return <div className="stat-item" ref={ref}><strong>{count.toLocaleString('en-IN')}{suffix}</strong><span>{label}</span></div>}
function Reveal({children}){const ref=useRef(null);useEffect(()=>{const node=ref.current;if(!node)return;const observer=new IntersectionObserver(([entry])=>{if(entry.isIntersecting){node.classList.add('is-visible');observer.disconnect()}},{threshold:.12});observer.observe(node);return()=>observer.disconnect()},[]);return <div className="reveal" ref={ref}>{children}</div>}
const experienceFeatures=[{number:'01',label:'Smart training',title:'SMART',accent:'TRAINING',kicker:'01 — PERFORMANCE',description:'Purposeful sessions that fit the way you want to move.',detail:'Build a stronger base with focused programming and a routine that works as hard as you do.',icon:Activity,visualClass:'stage-smart'},{number:'02',label:'Expert coaches',title:'EXPERT',accent:'COACHES',kicker:'02 — GUIDANCE',description:'Real guidance from people who know how to get results.',detail:'Train with clarity, refine your form and make every session count with an experienced eye beside you.',icon:Award,visualClass:'stage-coaches'},{number:'03',label:'Progress tracking',title:'PROGRESS',accent:'TRACKING',kicker:'03 — MOMENTUM',description:'See the small wins, then use them to go further.',detail:'Turn effort into evidence with milestones that keep your next goal within reach.',icon:TrendingUp,visualClass:'stage-progress'},{number:'04',label:'Flexible membership',title:'FLEXIBLE',accent:'MEMBERSHIP',kicker:'04 — FREEDOM',description:'Options that make showing up easier than making excuses.',detail:'Choose a rhythm that fits real life, so your membership keeps moving with you.',icon:ShieldCheck,visualClass:'stage-flexible'}];
function ExperienceSwitcher(){const [activeIndex,setActiveIndex]=useState(0);const active=experienceFeatures[activeIndex];const Icon=active.icon;return <div className="experience-stage"><div className="stage-index">{active.number} <span>/ 04</span></div><div className={'stage-visual '+active.visualClass} key={active.number}><Icon size={42}/><span>{active.title}<br/><em>{active.accent}</em></span><small>{active.kicker}</small><p className="stage-detail">{active.detail}</p></div><div className="experience-list">{experienceFeatures.map((feature,index)=><article className={'experience-item '+(index===activeIndex?'active':'')} key={feature.number} role="button" tabIndex="0" aria-current={index===activeIndex?'true':undefined} onClick={()=>setActiveIndex(index)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();setActiveIndex(index)}}}><span>{feature.number}</span><div><h3>{feature.label}</h3><p>{feature.description}</p></div><ArrowUpRight size={18}/></article>)}</div></div>}function JourneyStep({index,title,detail}){return <div className="journey-step"><span className="journey-number">{index}</span><div><h3>{title}</h3><p>{detail}</p></div><ArrowDown size={16}/></div>}function SectionTitle({eyebrow,title}){return <div className="section-title"><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div>}function MembershipPlans({onChoose}){const [loading,setLoading]=useState(true);const [plans,setPlans]=useState([]);useEffect(()=>{let active=true;gymApi.membershipPlans().then(response=>{const available=(Array.isArray(response.data)?response.data:[]).map(plan=>({...fallbackMembershipPlans.find(item=>normalizeMembershipPlan(item.name)===normalizeMembershipPlan(plan.name)),...plan})).filter(plan=>plan.name);if(active)setPlans(available.length?available:fallbackMembershipPlans)}).catch(()=>{if(active)setPlans(fallbackMembershipPlans)}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[]);return <section id="plans" className="membership-section"><div className="membership-inner"><header className="membership-heading"><span className="eyebrow">MEMBERSHIP OPTIONS</span><h2>Find the plan that fits your routine.</h2><p>Simple options, clear benefits, and the freedom to train at your own pace.</p></header><div className="membership-content">{loading&&<div className="membership-message"><span className="spinner"/>Loading membership plans...</div>}{!loading&&!plans.length&&<div className="membership-message">Membership plans will be available soon.</div>}{!loading&&plans.length>0&&<div className="membership-grid">{plans.map(plan=><article className={'membership-card '+(plan.recommended?'membership-card--featured':'')} key={plan.name}>{plan.recommended&&<span className="membership-badge">MOST POPULAR</span>}<div className="membership-card-head"><span className="membership-plan-name">{formatPlanName(plan.name)}</span><span className="membership-duration">{plan.duration}</span></div><div className="membership-price-value">{money(plan.price)}<small> / {plan.durationMonths===1?'month':'plan'}</small></div><p className="membership-description">{plan.description}</p><ul className="membership-benefits">{plan.features.map(feature=><li key={feature}><CheckCircle2 size={16}/><span>{feature}</span></li>)}</ul><button className={plan.recommended?'primary-btn membership-cta':'outline-btn membership-cta'} onClick={onChoose}>Sign in <ArrowUpRight size={15}/></button></article>)}</div>}</div></div></section>}function Login({onBack}){const {login,loading}=useAuth();const {pushToast}=useToast();const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [show,setShow]=useState(false);async function submit(e){e.preventDefault();try{await login(email.trim(),password)}catch(x){pushToast(errorMessage(x),'error')}}return <main className="auth-page"><div className="auth-art"><button className="back-link" onClick={onBack}>{'<-'} Back to website</button><Brand light/><div className="auth-message"><span className="eyebrow">OWNER PORTAL</span><h1>Run your gym<br/><em>with confidence.</em></h1><p>Manage your members, trainers and payments from one powerful workspace.</p></div><small>SECURE ACCESS / FITLIFE 2026</small></div><div className="auth-panel"><div className="mobile-only"><Brand/></div><div className="auth-box"><span className="eyebrow">WELCOME BACK</span><h2>Let's get moving.</h2><p>Sign in with the credentials provided by your gym owner.</p><form onSubmit={submit}><label>Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="owner@example.com" required/></label><label>Password<div className="password-input"><input type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password" required/><button type="button" onClick={()=>setShow(!show)}>{show?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></label><label className="remember"><input type="checkbox"/> Remember me</label><button className="primary-btn full" disabled={loading}>{loading?'Signing in...':'Sign in ->'}</button></form><div className="auth-help">Need help? <button onClick={()=>pushToast('Please contact your gym administrator.','info')}>Contact support</button></div></div></div></main>}function Dashboard(){const {session,logout,updateSession}=useAuth();const isOwner=role(session.role)==='OWNER';const [tab,setTab]=useState(isOwner?'dashboard':'profile');const [data,setData]=useState({members:[],trainers:[],payments:[],users:[],dashboard:{}});const [loading,setLoading]=useState(true);const {pushToast}=useToast();const setNotice=(message,type)=>pushToast(message,type);const [search,setSearch]=useState('');useEffect(()=>{let alive=true; (async()=>{try{const calls=isOwner?[gymApi.members(),gymApi.trainers(),gymApi.payments(),gymApi.users(),gymApi.dashboard()]:role(session.role)==='MEMBER'?[gymApi.memberProfile(),gymApi.myPayments()]:[gymApi.trainerProfile(),gymApi.myMembers()];const r=await Promise.allSettled(calls);if(alive){if(role(session.role)==='MEMBER'&&r[0].status==='fulfilled')console.log('Member Profile API Response:',r[0].value?.data);if(isOwner&&r[1].status==='fulfilled')console.log('Trainer API Response:',r[1].value?.data);if(!isOwner&&role(session.role)==='TRAINER'&&r[1].status==='fulfilled')console.log('Trainer Members API Response:',r[1].value?.data);if(isOwner&&r.some(x=>x.status==='rejected'))setNotice('One or more dashboard resources could not be loaded. Check the Network tab for the failing API request.');if(isOwner)setData({members:r[0].value?.data||[],trainers:r[1].value?.data||[],payments:r[2].value?.data||[],users:r[3].value?.data||[],dashboard:r[4].value?.data||{}});else if(role(session.role)==='MEMBER')setData({members:[r[0].value?.data].filter(Boolean),payments:r[1].value?.data||[]});else setData({trainers:[r[0].value?.data].filter(Boolean),members:r[1].value?.data||[]})}}catch(e){setNotice(errorMessage(e))}finally{if(alive)setLoading(false)}})();return()=>{alive=false}},[isOwner,session.role]);const recordMemberPayment=payment=>setData(current=>({...current,payments:[payment,...(Array.isArray(current.payments)?current.payments:[])]}));const current=data[tab]||[];const filtered=Array.isArray(current)?current.filter(x=>JSON.stringify(x).toLowerCase().includes(search.toLowerCase())):[];const title=tab==='dashboard'?'Good morning, '+displayNameFor(session):tab==='profile'?'My profile':tab.charAt(0).toUpperCase()+tab.slice(1);return <div className="dashboard-shell"><aside className="dashboard-side"><Brand light/><div className="side-user"><span className="side-user-avatar">{session.profileImageUrl?<img src={session.profileImageUrl} alt="Profile"/>:displayNameFor(session)[0].toUpperCase()}</span><div><b>{displayNameFor(session)}</b><small>{role(session.role)}</small></div></div><nav>{(isOwner?[['dashboard','Overview',Home],['profile','My profile',UserRound],['members','Members',Users],['trainers','Trainers',Dumbbell],['payments','Payments',CreditCard],['users','Users',UserRound]]:role(session.role)==='MEMBER'?[['profile','My profile',UserRound],['payments','My payments',CreditCard]]:[['profile','My profile',UserRound],['members','My members',Users]]).map(([id,label,I])=><button className={tab===id?'active':''} onClick={()=>{setTab(id);setSearch('')}} key={id}><I size={18}/>{label}</button>)}</nav><button className="side-logout" onClick={async()=>{await logout();pushToast('You have been logged out successfully.','success')}}>{'->'} Sign out</button></aside><main className="dashboard-main">{(!isOwner&&role(session.role)==='TRAINER'&&tab==='profile')&&<header className="dash-header"><div><span className="eyebrow">FITLIFE GYM / {tab.toUpperCase()}</span><h1>{title}</h1></div><div className="dash-avatar">{displayNameFor(session)[0].toUpperCase()}</div></header>}{loading?<div className="loading-state"><span className="spinner"/>Loading your workspace...</div>:tab==='dashboard'?<Overview data={{...data,ownerName:displayNameFor(session)}} onTab={setTab}/>:!isOwner&&role(session.role)==='MEMBER'&&tab==='payments'?<MemberPaymentsPage session={session} data={data} onPaymentSuccess={recordMemberPayment}/>:tab==='profile'?<ProfilePage session={session} onSessionUpdate={updateSession} pushToast={pushToast}/>:tab==='members'&&isOwner?<MembersPage members={data.members} trainers={data.trainers} users={data.users} setNotice={setNotice}/>:tab==='members'&&!isOwner&&role(session.role)==='TRAINER'?<TrainerMembersPage members={data.members}/>:tab==='users'&&isOwner?<UsersPage users={data.users} trainers={data.trainers} setNotice={setNotice} onUsersChange={users=>setData(current=>({...current,users}))} onTrainersChange={trainers=>setData(current=>({...current,trainers}))}/>:<ResourcePage title={title} rows={filtered} type={tab} search={search} setSearch={setSearch} owner={isOwner} setNotice={setNotice} reload={()=>{if(tab==='trainers')gymApi.trainers().then(r=>setData(current=>({...current,trainers:Array.isArray(r.data)?r.data:[]}))).catch(e=>setNotice(errorMessage(e)));if(tab==='payments')gymApi.payments().then(r=>setData(current=>({...current,payments:Array.isArray(r.data)?r.data:[]}))).catch(e=>setNotice(errorMessage(e)))}}/>}<FitLifeAssistant/></main></div>}
function membershipStatus(endDate){if(!endDate)return 'UNKNOWN';const end=new Date(endDate+'T23:59:59');const days=Math.ceil((end-new Date())/86400000);return days<0?'EXPIRED':days<=7?'EXPIRING SOON':'ACTIVE'}
function paymentStatusValue(payment){const value=String(payment?.paymentStatus||payment?.status||'PENDING').toUpperCase();return value==='CREATED'?'PENDING':value==='COMPLETED'||value==='SUCCESS'?'PAID':['PENDING','PROCESSING','PAID','FAILED'].includes(value)?value:'PENDING'}
function isPaid(payment){return paymentStatusValue(payment)==='PAID'}
function dateLabel(value){if(!value)return '';return new Date(value+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}
function Overview({data,onTab}){const d=data.dashboard||{};const members=Array.isArray(data.members)?data.members:[];const payments=Array.isArray(data.payments)?data.payments:[];const trainers=Array.isArray(data.trainers)?data.trainers:[];const users=Array.isArray(data.users)?data.users:[];const recentMembers=[...members].sort((a,b)=>String(b.id||'').localeCompare(String(a.id||''))).slice(0,5);const recentPayments=[...payments].sort((a,b)=>String(b.paymentDate||'').localeCompare(String(a.paymentDate||''))).slice(0,5);const expiring=members.map(m=>{const end=m.membershipEndDate;if(!end)return null;const days=Math.ceil((new Date(end+'T23:59:59')-new Date())/86400000);return {...m,days}}).filter(Boolean).filter(m=>m.days>=0&&m.days<=30).sort((a,b)=>a.days-b.days).slice(0,4);const revenue=d.totalRevenue??payments.reduce((sum,p)=>sum+Number(p.amount||0),0);const today=new Date().toLocaleDateString('en-IN',{weekday:'long',day:'2-digit',month:'long',year:'numeric'});return <div className="dash-body owner-overview"><div className="owner-welcome"><div><span className="eyebrow">FITLIFE GYM / OWNER OVERVIEW</span><h2>Good {new Date().getHours()<12?'Morning':new Date().getHours()<17?'Afternoon':'Evening'}, {data.ownerName||'Owner'} <span></span></h2><p>Here's what's happening at your gym today.</p></div><div className="owner-date"><span className="date-icon"></span><span>{today}</span><span className="notification-dot"></span></div></div><div className="metric-grid owner-metrics">{[['Total members',d.totalMembers??members.length,Users,'All registered members'],['Total trainers',d.totalTrainers??trainers.length,Dumbbell,'Your coaching team'],['Total users',d.totalUsers??users.length,UserRound,'All gym accounts'],['Total revenue',money(revenue),TrendingUp,'From recorded payments']].map(([label,value,I,caption])=><div className="metric owner-metric" key={label}><span>{label}<I size={19}/></span><b>{value}</b><small>{caption}</small></div>)}</div><div className="quick-actions"><div><span className="eyebrow">SHORTCUTS</span><h3>Quick actions</h3></div><div className="quick-action-list"><button onClick={()=>onTab('members')}><Plus size={16}/>Add member</button><button onClick={()=>onTab('trainers')}><Plus size={16}/>Add trainer</button><button onClick={()=>onTab('users')}><UserRound size={16}/>Create user</button><button onClick={()=>onTab('payments')}><CreditCard size={16}/>Add payment</button></div></div><div className="owner-grid"><section className="owner-panel"><div className="panel-heading"><div><span className="eyebrow">MEMBER DIRECTORY</span><h3>Recent members</h3></div><button onClick={()=>onTab('members')}>View all members </button></div>{recentMembers.length?<div className="mini-list">{recentMembers.map(m=><div className="mini-row" key={m.id}><span className="list-avatar">{String(m.name||'M')[0].toUpperCase()}</span><div className="mini-main"><b>{m.name||'Unnamed member'}</b><small>{m.phone||'No phone'}  {formatPlanName(m.membershipType)||'No plan'}</small></div><div className="mini-end"><small>{dateLabel(m.membershipEndDate)}</small><StatusBadge status={membershipStatus(m.membershipEndDate)}/></div></div>)}</div>:<div className="panel-empty">No members found yet.</div>}</section><section className="owner-panel"><div className="panel-heading"><div><span className="eyebrow">FINANCE</span><h3>Recent payments</h3></div><button onClick={()=>onTab('payments')}>View all payments </button></div>{recentPayments.length?<div className="mini-list">{recentPayments.map((p,i)=><div className="mini-row" key={p.paymentId||i}><span className="list-avatar payment-avatar"></span><div className="mini-main"><b>{p.memberName||`Member #${p.memberId||''}`}</b><small>{dateLabel(p.paymentDate)}  {p.paymentMethod||'Payment'}</small></div><div className="mini-end"><b>{money(p.amount)}</b><StatusBadge status={paymentStatusValue(p)}/></div></div>)}</div>:<div className="panel-empty">No payments found yet.</div>}</section></div><div className="owner-grid lower-grid"><section className="owner-panel expiry-panel"><div className="panel-heading"><div><span className="eyebrow">ATTENTION NEEDED</span><h3>Membership expiring soon</h3></div><span className="warning-count">{expiring.length} alerts</span></div>{expiring.length?<div className="expiry-list">{expiring.map(m=><div className="expiry-row" key={m.id}><span className="warning-icon">!</span><div><b>{m.name}</b><small>{formatPlanName(m.membershipType)||'Membership'}  expires {dateLabel(m.membershipEndDate)}</small></div><strong>{m.days===0?'Today':m.days===1?'Tomorrow':`${m.days} days`}</strong></div>)}</div>:<div className="panel-empty success-empty">All memberships are healthy for the next 30 days.</div>}</section><section className="owner-panel distribution-panel"><div className="panel-heading"><div><span className="eyebrow">MEMBERSHIP ANALYTICS</span><h3>Plan distribution</h3></div></div>{members.length?<div className="distribution-list">{Object.entries(members.reduce((acc,m)=>{const key=formatPlanName(m.membershipType)||'Unassigned';acc[key]=(acc[key]||0)+1;return acc},{})).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([name,count])=>{const percent=Math.round(count/members.length*100);return <div className="distribution-row" key={name}><div><b>{name}</b><span>{percent}%</span></div><div className="distribution-track"><i style={{width:`${percent}%`}}/></div></div>})}</div>:<div className="panel-empty">Add members to see plan analytics.</div>}</section></div></div>}
function memberTrainerId(member){return member?.trainerId??member?.trainer?.trainerId??member?.trainer?.id??''}
function StatusBadge({status}){const value=String(status||'PENDING').toUpperCase();return <span className={'status-badge '+value.toLowerCase().replace(/\s+/g,'-')}>{value}</span>}function MembersPage({members,trainers,users,setNotice}){const trainerOptions=Array.isArray(trainers)?trainers:[];const userOptions=Array.isArray(users)?users:[];const [items,setItems]=useState(Array.isArray(members)?members:[]);const [query,setQuery]=useState('');const [plan,setPlan]=useState('ALL');const [status,setStatus]=useState('ALL');const [trainer,setTrainer]=useState('ALL');const [modal,setModal]=useState(null);const [selected,setSelected]=useState(null);const [busy,setBusy]=useState(false);const [trainerLinks,setTrainerLinks]=useState(()=>{try{return JSON.parse(localStorage.getItem('fitlife_member_trainers')||'{}')}catch{return {}}});useEffect(()=>setItems(Array.isArray(members)?members:[]),[members]);const visibleItems=items.map(m=>memberTrainerId(m)?m:{...m,trainerId:trainerLinks[m.id]||''});const plans=[...new Set(items.map(m=>m.membershipType).filter(Boolean))];const filtered=visibleItems.filter(m=>{const q=query.trim().toLowerCase();return(!q||String(m.name||'').toLowerCase().includes(q))&&(plan==='ALL'||m.membershipType===plan)&&(status==='ALL'||membershipStatus(m.membershipEndDate)===status)&&(trainer==='ALL'||String(memberTrainerId(m))===trainer)});const openForm=(member=null)=>{setSelected(member);setModal(member?'edit':'add')};const save=async(payload)=>{setBusy(true);try{const result=modal==='add'?await gymApi.createMember(payload):await gymApi.updateMember(selected.id,payload);const saved=result.data;const savedId=saved?.id||selected?.id;const assignedTrainerId=payload.trainer?.id||payload.trainer?.trainerId||'';if(savedId){const nextLinks={...trainerLinks,[savedId]:assignedTrainerId};setTrainerLinks(nextLinks);localStorage.setItem('fitlife_member_trainers',JSON.stringify(nextLinks))}if(modal==='add')setItems(current=>[...current,saved]);else setItems(current=>current.map(m=>m.id===selected.id?{...m,...saved}:m));setNotice(modal==='add'?'Member added successfully.':'Member updated successfully.');setModal(null)}catch(e){setNotice(errorMessage(e))}finally{setBusy(false)}};const remove=async(member)=>{if(!window.confirm(`Delete ${member.name}? This action cannot be undone.`))return;setBusy(true);try{await gymApi.deleteMember(member.id);const nextLinks={...trainerLinks};delete nextLinks[member.id];setTrainerLinks(nextLinks);localStorage.setItem('fitlife_member_trainers',JSON.stringify(nextLinks));setItems(current=>current.filter(m=>m.id!==member.id));setNotice('Member deleted successfully.')}catch(e){setNotice(errorMessage(e))}finally{setBusy(false)}};return <div className="dash-body members-page"><div className="page-heading"><div><span className="eyebrow">MANAGEMENT / MEMBERS</span><h2>Members Management</h2><p>Manage all gym members and their membership information.</p></div><button className="primary-btn" onClick={()=>openForm()}><Plus size={16}/> Add Member</button></div><div className="member-filters"><div className="search"><Search size={16}/><input placeholder="Search members by name..." value={query} onChange={e=>setQuery(e.target.value)}/></div><select value={plan} onChange={e=>setPlan(e.target.value)}><option value="ALL">All Membership Types</option>{plans.map(p=><option key={p}>{p}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="ALL">All statuses</option><option>ACTIVE</option><option>EXPIRING SOON</option><option>EXPIRED</option></select><select value={trainer} onChange={e=>setTrainer(e.target.value)}><option value="ALL">All trainers</option>{trainerOptions.map(t=><option key={t.trainerId||t.id} value={t.trainerId||t.id}>{t.name}</option>)}</select></div><div className="member-table-card"><div className="table-summary"><b>{filtered.length} members</b><span>Updated from your backend</span></div>{filtered.length?<div className="table-wrap"><table className="members-table"><thead><tr><th>Name</th><th>Phone</th><th>Membership Type</th><th>Trainer</th><th>Membership End Date</th><th>Status</th><th>Actions</th></tr></thead><tbody>{filtered.map(m=>{const st=membershipStatus(m.membershipEndDate);const t=trainerOptions.find(x=>String(x.trainerId||x.id)===String(memberTrainerId(m)));return <tr key={m.id}><td><div className="member-cell"><span className="list-avatar">{String(m.name||'M')[0].toUpperCase()}</span><span><b>{m.name||'Unnamed member'}</b><small>Member #{m.id}</small></span></div></td><td>{m.phone||''}</td><td>{formatPlanName(m.membershipType)}</td><td>{t?.name||m.trainerName||'Not assigned'}</td><td>{dateLabel(m.membershipEndDate)}</td><td><StatusBadge status={st}/></td><td><div className="action-buttons"><button title="View" onClick={()=>{setSelected(m);setModal('view')}}><Eye size={15}/></button><button title="Edit" onClick={()=>openForm(m)}><Sparkles size={15}/></button><button title="Delete" className="danger-icon" disabled={busy} onClick={()=>remove(m)}><Trash2 size={15}/></button></div></td></tr>})}</tbody></table></div>:<div className="empty-state"><Users size={25}/><b>No members found</b><span>Try changing your search or filters.</span></div>}</div>{modal==='view'&&selected&&<Modal title="Member details" onClose={()=>setModal(null)}><div className="details-modal"><div className="detail-hero"><span className="profile-big">{String(selected.name||'M')[0]}</span><div><span className="eyebrow">MEMBER #{selected.id}</span><h3>{selected.name}</h3><StatusBadge status={membershipStatus(selected.membershipEndDate)}/></div></div><div className="detail-grid">{[['Age',selected.age],['Phone',selected.phone],['Membership',formatPlanName(selected.membershipType)],['Start date',dateLabel(selected.membershipStartDate)],['End date',dateLabel(selected.membershipEndDate)],['Trainer',trainerOptions.find(t=>String(t.trainerId||t.id)===String(memberTrainerId(selected)))?.name||'Not assigned']].map(([label,value])=><div key={label}><small>{label}</small><b>{value||''}</b></div>)}</div></div></Modal>}{(modal==='add'||modal==='edit')&&<MembershipFormView member={selected} trainers={trainers} users={users} busy={busy} onClose={()=>setModal(null)} onSave={save} Modal={Modal} pushToast={setNotice} money={money}/>}</div>}
function LegacyMemberForm({member,trainers,users,busy,onClose,onSave}){const {pushToast}=useToast();const [form,setForm]=useState({name:member?.name||'',age:member?.age||'',phone:member?.phone||'',membershipType:member?.membershipType||'',membershipStartDate:member?.membershipStartDate||'',membershipEndDate:member?.membershipEndDate||'',trainerId:member?.trainerId||member?.trainer?.trainerId||'',userId:member?.userId||member?.user?.id||''});const submit=e=>{e.preventDefault();if(new Date(form.membershipEndDate)<new Date(form.membershipStartDate))return pushToast('End date must be after the start date.','error');const payload={name:form.name.trim(),age:Number(form.age),phone:form.phone.trim(),membershipType:normalizeMembershipPlan(form.membershipType).trim(),membershipStartDate:form.membershipStartDate,membershipEndDate:form.membershipEndDate};if(form.trainerId)payload.trainer={id:Number(form.trainerId)};if(form.userId)payload.user={id:Number(form.userId)};onSave(payload)};return <Modal title={member?'Edit member':'Add member'} onClose={onClose}><form className="member-form" onSubmit={submit}><label>Full name<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Age<input required type="number" min="1" max="120" value={form.age} onChange={e=>setForm({...form,age:e.target.value})}/></label><label>Phone<input required value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>Membership type<select required value={form.membershipType} onChange={e=>setForm(current=>({...current,membershipType:e.target.value,membershipEndDate:calculateMembershipEndDate(current.membershipStartDate,e.target.value)}))}><option value="">Select membership type</option><option value="MONTHLY">Monthly</option><option value="QUARTERLY">Quarterly</option><option value="YEARLY">Yearly</option></select></label><div className="membership-price"><small>Membership price</small><b>{form.membershipType?`\u20B9${membershipPrices[form.membershipType]}`:'Select a plan'}</b></div><label>Start date<input required type="date" value={form.membershipStartDate} onChange={e=>setForm(current=>({...current,membershipStartDate:e.target.value,membershipEndDate:calculateMembershipEndDate(e.target.value,current.membershipType)}))}/></label><label>End date<input required readOnly type="date" value={form.membershipEndDate} onChange={e=>setForm({...form,membershipEndDate:e.target.value})}/></label><label>Assigned trainer<select value={form.trainerId} onChange={e=>setForm({...form,trainerId:e.target.value})}><option value="">No trainer assigned</option>{trainers.map(t=><option key={t.trainerId||t.id} value={t.trainerId||t.id}>{t.name}{t.specialty?` - ${t.specialty}`:''}</option>)}</select></label><label>User account<select value={form.userId} onChange={e=>setForm({...form,userId:e.target.value})}><option value="">No linked account</option>{users.filter(u=>!u.role||String(u.role).toUpperCase()==='MEMBER').map(u=><option key={u.id} value={u.id}>{u.username||'Unnamed'} - {u.email}</option>)}</select></label><div className="modal-actions"><button type="button" className="outline-btn" onClick={onClose}>Cancel</button><button className="primary-btn" disabled={busy}>{busy?'Saving...':'Save member'}</button></div></form></Modal>}
function MemberPaymentsPage({session,data,onPaymentSuccess}){const {pushToast}=useToast();const member=data.members?.[0]||{};const normalizeList=value=>Array.isArray(value)?value:Array.isArray(value?.payments)?value.payments:Array.isArray(value?.data)?value.data:[];const [payments,setPayments]=useState(normalizeList(data.payments));const [paymentStatus,setPaymentStatus]=useState(paymentStatusValue([...normalizeList(data.payments)].sort((a,b)=>String(b.paymentDate||'').localeCompare(String(a.paymentDate||'')))[0]));const plan=member.membershipType||'Not assigned';const price=membershipPrices[plan];useEffect(()=>setPayments(normalizeList(data.payments)),[data.payments]);const latest=[...payments].sort((a,b)=>String(b.paymentDate||'').localeCompare(String(a.paymentDate||'')))[0];const paid=isPaid({paymentStatus});const normalizeStatus=value=>paymentStatusValue({paymentStatus:value});const startPayment=async()=>{if(!price){pushToast('Select a valid membership plan before payment.','error');return}const key=import.meta.env.VITE_RAZORPAY_KEY_ID;if(!key){pushToast('Razorpay is not configured. Add VITE_RAZORPAY_KEY_ID to the frontend environment file.','error');return}setPaymentStatus('PROCESSING');pushToast('Processing your payment...','info');try{const orderResponse=await gymApi.createRazorpayOrder({amount:price,memberId:Number(member.id)});const order=orderResponse.data;if(!order?.orderId)throw new Error('Unable to create Razorpay order.');if(!window.Razorpay){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=resolve;script.onerror=reject;document.body.appendChild(script)})}const checkout=new window.Razorpay({key:order.keyId||key,order_id:order.orderId,amount:order.amount||price*100,currency:order.currency||'INR',name:'FitLife Gym',description:`${plan} Membership`,prefill:{name:member.name||displayNameFor(session),email:session.email||''},notes:{memberId:String(member.id||'')},theme:{color:'#173a2e'},handler:async response=>{try{const verified=await gymApi.verifyRazorpayPayment({orderId:response.razorpay_order_id,paymentId:response.razorpay_payment_id,signature:response.razorpay_signature});const refreshed=await gymApi.myPayments();const success={...verified.data,paymentId:verified.data?.paymentId||response.razorpay_payment_id,razorpayPaymentId:response.razorpay_payment_id,amount:price,paymentDate:new Date().toISOString().slice(0,10),membershipType:plan,paymentStatus:'PAID',status:'PAID'};setPaymentStatus('PAID');setPayments(normalizeList(refreshed.data).length?normalizeList(refreshed.data):[success]);onPaymentSuccess?.(success);pushToast('Payment successful. Your payment history has been refreshed.','success')}catch(error){pushToast(errorMessage(error),'error')}}});checkout.on('payment.failed',async response=>{setPaymentStatus('FAILED');pushToast(response.error?.description||'Payment failed. Please try again.','error');try{await gymApi.markRazorpayPaymentFailed({orderId:response.error?.metadata?.order_id||order.orderId})}catch{}});checkout.open()}catch(error){setPaymentStatus('FAILED');pushToast(errorMessage(error),'error')}};return <div className="dash-body payments-page"><div className="page-heading"><div><span className="eyebrow">MEMBER PORTAL / PAYMENTS</span><h2>My Payments</h2><p>View your complete membership payment history.</p></div><span className="record-count">{payments.length} payments</span></div>{!paid&&<section className="member-membership-panel payment-summary-card pending-payment-card"><div className="panel-heading"><div><span className="eyebrow">PAYMENT DUE</span><h3>Complete your membership payment</h3></div><button type="button" className="primary-btn pay-now-btn" onClick={startPayment}>Pay Now</button></div><div className="payment-summary-grid"><div><small>Membership Plan</small><b>{plan}</b></div><div><small>Fixed Membership Amount</small><b>{price?`\u20B9${price}`:'-'}</b></div><div><small>Payment Status</small><StatusBadge status={paymentStatus}/></div><div><small>Due Date</small><b>{dateLabel(member.membershipEndDate)||'-'}</b></div></div></section>}{payments.length?<div className="member-table-card"><div className="table-summary"><b>Payment history</b><span>{session.email||'Member account'}</span></div><div className="table-wrap"><table className="payments-table"><thead><tr><th>Payment ID</th><th>Membership Plan</th><th>Amount</th><th>Payment Status</th><th>Payment Date</th><th>Razorpay Payment ID</th></tr></thead><tbody>{payments.map((payment,index)=><tr key={payment.paymentId||payment.id||payment.razorpayPaymentId||index}><td>{payment.paymentId||payment.id||'-'}</td><td>{payment.membershipType||payment.plan||plan}</td><td>{money(payment.amount||price)}</td><td><StatusBadge status={normalizeStatus(payment.paymentStatus||payment.status)}/></td><td>{dateLabel(payment.paymentDate)||'-'}</td><td>{payment.razorpayPaymentId||'-'}</td></tr>)}</tbody></table></div></div>:<div className="member-table-card"><div className="empty-state"><CreditCard size={25}/><b>No payments found</b><span>Your payment history will appear here after a payment is recorded.</span></div></div>}</div>}function LegacyMemberDashboard({session,data,onPaymentSuccess}){const {pushToast}=useToast();const member=data.members?.[0]||{};const payments=Array.isArray(data.payments)?data.payments:[];const latestPayment=[...payments].sort((a,b)=>String(b.paymentDate||'').localeCompare(String(a.paymentDate||'')))[0];const plan=member.membershipType||'Not assigned';const price=membershipPrices[plan];const trainer=member.trainerName||'Not assigned';const [paymentStatus,setPaymentStatus]=useState(paymentStatusValue(latestPayment));const isPaymentPaid=paymentStatus==='PAID';const memberStatusValue=!isPaymentPaid?'PAYMENT PENDING':member.membershipEndDate&&new Date(member.membershipEndDate+'T23:59:59')>=new Date()?'ACTIVE':'EXPIRED';const memberPaymentStatus=paymentStatus;const startPayment=async()=>{if(!price){pushToast('Select a valid membership plan before payment.','error');return}const key=import.meta.env.VITE_RAZORPAY_KEY_ID;if(!key){pushToast('Razorpay is not configured. Add VITE_RAZORPAY_KEY_ID to the frontend environment file.','error');return}setPaymentStatus('PROCESSING');pushToast('Processing your payment...','info');try{const orderResponse=await gymApi.createRazorpayOrder({amount:price,memberId:Number(member.id)});const order=orderResponse.data;if(!order?.orderId)throw new Error('Unable to create Razorpay order.');if(!window.Razorpay){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=resolve;script.onerror=reject;document.body.appendChild(script)})}const checkout=new window.Razorpay({key:order.keyId||key,order_id:order.orderId,amount:order.amount||price*100,currency:order.currency||'INR',name:'FitLife Gym',description:`${plan} Membership`,prefill:{name:member.name||displayNameFor(session),email:session.email||''},notes:{memberId:String(member.id||'')},theme:{color:'#173a2e'},handler:async response=>{try{const verified=await gymApi.verifyRazorpayPayment({orderId:response.razorpay_order_id,paymentId:response.razorpay_payment_id,signature:response.razorpay_signature});const successfulPayment={...verified.data,paymentId:verified.data?.paymentId||response.razorpay_payment_id,razorpayPaymentId:response.razorpay_payment_id,amount:price,paymentDate:new Date().toISOString().slice(0,10),membershipType:plan,paymentStatus:'PAID',status:'PAID'};setPaymentStatus('PAID');onPaymentSuccess?.(successfulPayment);pushToast(`Payment successful. Razorpay payment ID: ${response.razorpay_payment_id}.`,'success')}catch(error){pushToast(errorMessage(error),'error')}}});checkout.on('payment.failed',async response=>{setPaymentStatus('FAILED');pushToast(response.error?.description||'Payment failed. Please try again.','error');try{await gymApi.markRazorpayPaymentFailed({orderId:response.error?.metadata?.order_id||order.orderId})}catch{}});checkout.open()}catch{setPaymentStatus('FAILED');pushToast('Unable to load Razorpay Checkout. Please check your internet connection.','error')}};return <div className="dash-body member-dashboard"><div className="member-welcome"><div><span className="eyebrow">MEMBER PORTAL</span><h2>Welcome, {member.name||displayNameFor(session)}</h2><p>Here is your current membership information.</p></div><span className="profile-big">{String(member.name||displayNameFor(session)||'M')[0].toUpperCase()}</span></div><section className="member-membership-panel"><div className="panel-heading"><div><span className="eyebrow">YOUR MEMBERSHIP</span><h3>Membership details</h3></div><StatusBadge status={memberPaymentStatus}/></div><div className="member-plan-highlight"><div><small>Membership Plan</small><b>{plan}</b></div><div><small>Membership Fee</small><b>{price?`\u20B9${price}`:'-'}</b></div></div><div className="detail-grid member-detail-grid"><div><small>Member Name</small><b>{member.name||'-'}</b></div><div><small>Payment Status</small><b><StatusBadge status={memberPaymentStatus}/></b></div><div><small>Membership Status</small><b><StatusBadge status={memberStatusValue}/></b></div><div><small>Start Date</small><b>{dateLabel(member.membershipStartDate)||'-'}</b></div><div><small>End Date</small><b>{dateLabel(member.membershipEndDate)||'-'}</b></div><div><small>Assigned Trainer</small><b>{trainer}</b></div><div><small>Phone</small><b>{member.phone||'-'}</b></div></div></section><section className="member-membership-panel payment-summary-card"><div className="panel-heading"><div><span className="eyebrow">PAYMENT SUMMARY</span><h3>Your payment summary</h3></div>{!isPaymentPaid&&<button type="button" className="primary-btn pay-now-btn" onClick={startPayment}>Pay Now</button>}</div><div className="payment-summary-grid"><div><small>Membership Plan</small><b>{plan}</b></div><div><small>Fixed Membership Amount</small><b>{price?`\u20B9${price}`:'-'}</b></div><div><small>Payment Status</small><StatusBadge status={memberPaymentStatus}/></div><div><small>Due Date</small><b>{dateLabel(latestPayment?.dueDate||latestPayment?.paymentDueDate||member.membershipEndDate)||'-'}</b></div></div></section><section className="member-membership-panel"><div className="panel-heading"><div><span className="eyebrow">PAYMENTS</span><h3>Recent payment</h3></div></div>{latestPayment?<div className="payment-summary"><div><small>Amount</small><b>{money(latestPayment.amount)}</b></div><div><small>Payment Date</small><b>{dateLabel(latestPayment.paymentDate)||'-'}</b></div><div><small>Status</small><StatusBadge status={paymentStatus}/></div></div>:<div className="panel-empty">No payment information available yet.</div>}</section></div>}function TrainerProfile({data}){const {pushToast}=useToast();const [profile,setProfile]=useState(data.trainers?.[0]||{});const [editing,setEditing]=useState(false);const [saving,setSaving]=useState(false);const [form,setForm]=useState({name:'',phone:'',age:'',specialty:'',email:''});useEffect(()=>setProfile(data.trainers?.[0]||{}),[data.trainers]);const value=v=>v===null||v===undefined||String(v).trim()===''?'Not provided':v;const openEdit=()=>{console.log('Trainer profile before edit:',profile);setForm({name:profile.name||'',phone:profile.phone||'',age:profile.age??'',specialty:profile.specialty||'',email:profile.email||''});setEditing(true)};const submit=async e=>{e.preventDefault();const name=form.name.trim(),phone=form.phone.trim(),specialty=form.specialty.trim(),age=String(form.age).trim();if(!name||!phone||!specialty||!age){pushToast('Full name, phone number, age and specialty are required.','error');return}if(!/^\+?[0-9\s()\-]{7,20}$/.test(phone)){pushToast('Please enter a valid phone number.','error');return}if(!/^\d+$/.test(age)||Number(age)<1||Number(age)>120){pushToast('Age must be between 1 and 120.','error');return}setSaving(true);try{const response=await gymApi.updateMyTrainerProfile({name,phone,age:Number(age),specialty});console.log('Trainer Profile Update API Response:',response?.data);setProfile(response.data||profile);setEditing(false)}catch(err){pushToast(errorMessage(err),'error')}finally{setSaving(false)}};const initial=String(profile.name||'T').trim().charAt(0).toUpperCase();return <div className="dash-body trainer-profile-page"><div className="profile-box trainer-profile-card"><div className="profile-top trainer-profile-top"><span className="profile-big trainer-avatar">{initial}</span><div><span className="eyebrow">TRAINER PROFILE</span><h2>{value(profile.name)}</h2><p>{value(profile.email)}</p></div><button type="button" className="primary-btn trainer-edit-profile-btn" onClick={openEdit}>Edit Profile</button></div><div className="profile-grid trainer-profile-grid">{[['Full Name',profile.name],['Email',profile.email],['Phone Number',profile.phone],['Age',profile.age],['Specialty',profile.specialty],['Trainer ID',profile.trainerId],['Account/User ID',profile.userId]].map(([label,item])=><div key={label}><small>{label}</small><b>{value(item)}</b></div>)}</div></div>{editing&&<Modal title="Edit Profile" onClose={()=>!saving&&setEditing(false)}><form className="modal-form trainer-profile-edit-form" onSubmit={submit}><div className="form-section-title">Personal Information</div><label>Full Name<input required disabled={saving} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Email<input type="email" readOnly className="readonly-field" value={form.email}/></label><label>Phone Number<input required disabled={saving} value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>Age<input required type="number" min="1" max="120" disabled={saving} value={form.age} onChange={e=>setForm({...form,age:e.target.value})}/></label><div className="form-section-title">Professional Information</div><label>Specialty<input required disabled={saving} value={form.specialty} onChange={e=>setForm({...form,specialty:e.target.value})}/></label><div className="modal-actions"><button type="button" className="outline-btn" disabled={saving} onClick={()=>setEditing(false)}>Cancel</button><button className="primary-btn" disabled={saving}>{saving?'Saving...':'Save changes'}</button></div></form></Modal>}</div>}
function TrainerMembersPage({members}){const [query,setQuery]=useState('');const items=Array.isArray(members)?members:[];const filtered=items.filter(member=>String(member.name||'').toLowerCase().includes(query.trim().toLowerCase()));return <div className="dash-body trainer-members-page"><div className="page-heading"><div><span className="eyebrow">TRAINER PORTAL / MY MEMBERS</span><h2>My Members</h2><p>Members assigned to your trainer account.</p></div><span className="record-count">{items.length} {items.length===1?'member':'members'}</span></div><div className="toolbar"><div className="search"><Search size={16}/><input placeholder="Search members by name..." value={query} onChange={e=>setQuery(e.target.value)}/></div><span>{filtered.length} shown</span></div>{filtered.length?<div className="member-table-card"><div className="table-summary"><b>{items.length} assigned {items.length===1?'member':'members'}</b><span>Live data from your backend</span></div><div className="table-wrap"><table className="trainer-members-table"><thead><tr><th>Member Name</th><th>Age</th><th>Phone</th><th>Membership Plan</th><th>Start Date</th><th>End Date</th><th>Payment Status</th></tr></thead><tbody>{filtered.map(member=><tr key={member.memberId}><td><div className="member-cell"><span className="list-avatar">{String(member.name||'M')[0].toUpperCase()}</span><b>{member.name||'Not provided'}</b></div></td><td>{member.age??'Not provided'}</td><td>{member.phone||'Not provided'}</td><td>{formatPlanName(member.membershipType)||'Not provided'}</td><td>{dateLabel(member.membershipStartDate)||'Not provided'}</td><td>{dateLabel(member.membershipEndDate)||'Not provided'}</td><td><StatusBadge status={member.paymentStatus||'PENDING'}/></td></tr>)}</tbody></table></div></div>:<div className="member-table-card"><div className="empty-state"><Users size={25}/><b>{items.length?'No matching members':'No members assigned'}</b><span>{items.length?'Try another member name.':'Members assigned to you will appear here.'}</span></div></div>}</div>}
